describe('PgLeavePolicyRepository', () => {
  let repo: PgLeavePolicyRepository;

  beforeEach(() => {
    repo = new PgLeavePolicyRepository();
    mockQuery.mockReset();
  });

  describe('findById', () => {
    it('should return LeavePolicy when row exists', async () => {
      const row = makePolicyRow();
      mockQuery.mockResolvedValueOnce({ rows: [row] });

      const result = await repo.findById('pol-1');

      expect(result).toEqual(makePolicy());
      expect(mockQuery).toHaveBeenCalledWith(
        'SELECT * FROM leave_policies WHERE id = $1',
        ['pol-1'],
      );
    });

    it('should return null when no matching row found', async () => {
      mockQuery.mockResolvedValueOnce({ rows: [] });

      const result = await repo.findById('nonexistent');

      expect(result).toBeNull();
    });
  });

  describe('findByLeaveType', () => {
    it('should return LeavePolicy when leave type matches', async () => {
      const row = makePolicyRow({ leave_type: 'sick' });
      mockQuery.mockResolvedValueOnce({ rows: [row] });

      const result = await repo.findByLeaveType(LeaveType.sick);

      expect(result).toEqual(makePolicy({ leaveType: LeaveType.sick }));
      expect(mockQuery).toHaveBeenCalledWith(
        'SELECT * FROM leave_policies WHERE leave_type = $1',
        ['sick'],
      );
    });

    it('should return null when no policy exists for the leave type', async () => {
      mockQuery.mockResolvedValueOnce({ rows: [] });

      const result = await repo.findByLeaveType(LeaveType.emergency);

      expect(result).toBeNull();
    });

    it('should return at most one policy per leave type', async () => {
      const row = makePolicyRow({ leave_type: 'annual' });
      mockQuery.mockResolvedValueOnce({ rows: [row] });

      const result = await repo.findByLeaveType(LeaveType.annual);

      expect(result).not.toBeNull();
      expect(result!.leaveType).toBe(LeaveType.annual);
    });
  });

  describe('findAllActive', () => {
    it('should return only policies where is_active = true', async () => {
      const row1 = makePolicyRow({ id: 'pol-1', is_active: true });
      const row2 = makePolicyRow({ id: 'pol-2', is_active: true, leave_type: 'sick' });
      mockQuery.mockResolvedValueOnce({ rows: [row1, row2] });

      const result = await repo.findAllActive();

      expect(result).toHaveLength(2);
      expect(result[0].isActive).toBe(true);
      expect(result[1].isActive).toBe(true);
      expect(mockQuery).toHaveBeenCalledWith(
        'SELECT * FROM leave_policies WHERE is_active = true',
      );
    });

    it('should return empty array when no active policies exist', async () => {
      mockQuery.mockResolvedValueOnce({ rows: [] });

      const result = await repo.findAllActive();

      expect(result).toEqual([]);
    });
  });

  describe('create', () => {
    it('should insert a new policy and return the created LeavePolicy', async () => {
      const input = {
        policyName: 'Sick Leave Policy',
        leaveType: LeaveType.sick,
        entitlementDays: 10,
        accrualRate: 0.83,
        maxAccumulation: 15,
        minimumNoticeDays: 1,
        requiresManagerApproval: false,
        isActive: true,
      };
      const row = makePolicyRow({
        id: 'pol-2',
        policy_name: 'Sick Leave Policy',
        leave_type: 'sick',
        entitlement_days: 10,
        accrual_rate: 0.83,
        max_accumulation: 15,
        minimum_notice_days: 1,
        requires_manager_approval: false,
        is_active: true,
      });
      mockQuery.mockResolvedValueOnce({ rows: [row] });

      const result = await repo.create(input);

      expect(result).toEqual(
        makePolicy({
          id: 'pol-2',
          policyName: 'Sick Leave Policy',
          leaveType: LeaveType.sick,
          entitlementDays: 10,
          accrualRate: 0.83,
          maxAccumulation: 15,
          minimumNoticeDays: 1,
          requiresManagerApproval: false,
        }),
      );
      expect(mockQuery).toHaveBeenCalledWith(
        expect.stringContaining('INSERT INTO leave_policies'),
        [
          'Sick Leave Policy',
          'sick',
          10,
          0.83,
          15,
          1,
          false,
          true,
        ],
      );
    });
  });

  describe('update', () => {
    it('should update policy fields and return the updated LeavePolicy', async () => {
      const row = makePolicyRow({
        entitlement_days: 25,
        minimum_notice_days: 5,
      });
      mockQuery.mockResolvedValueOnce({ rows: [row] });

      const result = await repo.update('pol-1', {
        entitlementDays: 25,
        minimumNoticeDays: 5,
      });

      expect(result).toEqual(
        makePolicy({ entitlementDays: 25, minimumNoticeDays: 5 }),
      );
      expect(mockQuery).toHaveBeenCalledWith(
        expect.stringContaining('UPDATE leave_policies SET'),
        expect.arrayContaining(['pol-1', 25, 5]),
      );
    });

    it('should return null when policy does not exist', async () => {
      mockQuery.mockResolvedValueOnce({ rows: [] });

      const result = await repo.update('nonexistent', { entitlementDays: 30 });

      expect(result).toBeNull();
    });

    it('should return existing policy when no valid keys are provided', async () => {
      const row = makePolicyRow();
      mockQuery.mockResolvedValueOnce({ rows: [row] });

      const result = await repo.update('pol-1', {});

      expect(result).toEqual(makePolicy());
    });
  });
});
import { LeavePolicyService } from '../../../../src/modules/leave-policy/leave-policy.service';
import { ILeavePolicyRepository, LeavePolicy } from '../../../../src/modules/leave-policy/leave-policy.model';
import { LeaveType } from '../../../../src/shared/types';

function makePolicy(overrides: Partial<LeavePolicy> = {}): LeavePolicy {
  return {
    id: 'pol-1',
    policyName: 'Annual Leave Policy',
    leaveType: LeaveType.annual,
    entitlementDays: 20,
    accrualRate: 1.67,
    maxAccumulation: 30,
    minimumNoticeDays: 3,
    requiresManagerApproval: true,
    isActive: true,
    createdAt: new Date('2020-01-01T00:00:00Z'),
    updatedAt: new Date('2020-01-01T00:00:00Z'),
    ...overrides,
  };
}

function createMockRepo(): jest.Mocked<ILeavePolicyRepository> {
  return {
    findById: jest.fn(),
    findByLeaveType: jest.fn(),
    findAllActive: jest.fn(),
    create: jest.fn(),
    update: jest.fn(),
  };
}

describe('LeavePolicyService', () => {
  let service: LeavePolicyService;
  let mockRepo: jest.Mocked<ILeavePolicyRepository>;

  beforeEach(() => {
    mockRepo = createMockRepo();
    service = new LeavePolicyService(mockRepo);
  });

  describe('getPolicyForLeaveType', () => {
    it('should delegate to repository.findByLeaveType with the given leaveType', async () => {
      const policy = makePolicy();
      mockRepo.findByLeaveType.mockResolvedValueOnce(policy);

      const result = await service.getPolicyForLeaveType(LeaveType.annual);

      expect(result).toEqual(policy);
      expect(mockRepo.findByLeaveType).toHaveBeenCalledWith(LeaveType.annual);
    });

    it('should return null when repository returns null', async () => {
      mockRepo.findByLeaveType.mockResolvedValueOnce(null);

      const result = await service.getPolicyForLeaveType(LeaveType.emergency);

      expect(result).toBeNull();
    });

    it('should never throw', async () => {
      mockRepo.findByLeaveType.mockResolvedValueOnce(null);

      await expect(
        service.getPolicyForLeaveType(LeaveType.annual),
      ).resolves.toBeNull();
    });
  });

  describe('validateEntitlement', () => {
    it('should return true when requestedDays <= entitlementDays', async () => {
      const policy = makePolicy({ entitlementDays: 20 });
      mockRepo.findByLeaveType.mockResolvedValueOnce(policy);

      const result = await service.validateEntitlement(
        'emp-1',
        LeaveType.annual,
        10,
      );

      expect(result).toBe(true);
    });

    it('should return true when requestedDays equals entitlementDays exactly', async () => {
      const policy = makePolicy({ entitlementDays: 20 });
      mockRepo.findByLeaveType.mockResolvedValueOnce(policy);

      const result = await service.validateEntitlement(
        'emp-1',
        LeaveType.annual,
        20,
      );

      expect(result).toBe(true);
    });

    it('should return false when requestedDays > entitlementDays', async () => {
      const policy = makePolicy({ entitlementDays: 20 });
      mockRepo.findByLeaveType.mockResolvedValueOnce(policy);

      const result = await service.validateEntitlement(
        'emp-1',
        LeaveType.annual,
        25,
      );

      expect(result).toBe(false);
    });

    it('should return false when no policy exists for the given leaveType', async () => {
      mockRepo.findByLeaveType.mockResolvedValueOnce(null);

      const result = await service.validateEntitlement(
        'emp-1',
        LeaveType.emergency,
        5,
      );

      expect(result).toBe(false);
    });

    it('should return true when requestedDays is 0 and policy exists', async () => {
      const policy = makePolicy({ entitlementDays: 20 });
      mockRepo.findByLeaveType.mockResolvedValueOnce(policy);

      const result = await service.validateEntitlement(
        'emp-1',
        LeaveType.annual,
        0,
      );

      expect(result).toBe(true);
    });
  });
});
